import{_ as e}from"./chunks/7967fadb98730412c428.j0S7uuHD.js";import{_ as r,C as a,o as s,c as n,j as t,a as l,E as i,a6 as g}from"./chunks/framework.CnPv4DE1.js";const b=JSON.parse('{"title":"如何在社交媒体上真正实现增长（即使你是0粉起步）","description":"","frontmatter":{"title":"如何在社交媒体上真正实现增长（即使你是0粉起步）","originalTitle":"How To Actually Grow On Social Media (Even If You Have 0 Followers)","date":"2023-09-30","originalUrl":"https://thedankoe.com/letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you/","minutes":14,"sourceHash":"176023573e20daad43e142df5c502e60495385f2609145a89d0f71051c245d4f","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you/"}]]},"headers":[],"relativePath":"letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you.md","filePath":"letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you.md"}'),h={name:"letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you.md"};function u(c,p,d,m,f,w){const o=a("ArticleMeta");return s(),n("div",null,[p[0]||(p[0]=t("h1",{id:"如何在社交媒体上真正实现增长-即使你是0粉起步",tabindex:"-1"},[l("如何在社交媒体上真正实现增长（即使你是0粉起步） "),t("a",{class:"header-anchor",href:"#如何在社交媒体上真正实现增长-即使你是0粉起步","aria-label":'Permalink to "如何在社交媒体上真正实现增长（即使你是0粉起步）"'},"​")],-1)),i(o),p[1]||(p[1]=g('<p><a href="https://www.youtube.com/embed/iD1jJMz9zOs?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我有很多粉丝。</p><p>（没有什么比一点自恋更适合作为开场白了，对吧？）</p><p>说点正经的，我这么说只是为了给这次对话定个基调。这是写给那些想在社交媒体上实现增长的人的。</p><p>我的读者群并不总是有这么庞大。</p><p>这显而易见，但你也知道人性是如何运作的。</p><p>人们会根据对你的了解勾勒出一个形象，并以此为基础做出评判。</p><p>人们看到我有280万粉丝，就不会想到我曾经也只有500个粉丝，顶着一个让人尴尬到脚趾抠地的主页。</p><p>极少有人能完成那种“永远不以貌取人”所必需的自我修行。</p><p>我在社交媒体上的首次尝试，是以摄影师的身份开始的。</p><p>我热爱拍照，但除了接了几个50美元的毕业照跟拍之外，我根本没法变现（而且那些照片拍得很烂，对不住那些花钱请我拍的人了）。</p><p>我会在Instagram上发我的照片，带上一堆从其他账号抄来的标签，期盼着有朝一日莫名其妙就能涨到10万粉。我毫无变现计划可言。</p><p>后来，修图开始越来越吸引我的注意。</p><p>我开始纯粹为了能对照片进行一些疯狂的后期编辑而去拍照。</p><p>我整天疯狂刷YouTube视频，学习Photoshop和Lightroom。</p><p>最终，我偶然发现了一个名叫Visuals Of Julius的家伙。</p><p>他会发布这些超现实的照片。这是我以前从未见过的东西。</p><p>我想做他做的事。</p><p>于是，我继续疯狂刷YouTube。</p><p>我从室友那里借了些阿德拉（Adderall，注：一种精神兴奋剂），把自己锁在房间里，听着重摇滚，随心所欲地搞创作。</p><p>这是我最喜欢的作品之一：</p><p><img src="'+e+'" alt=""></p><p>也就是在这个时候，事情开始变得真切起来。</p><p>我开始揭开社交媒体增长的“秘密”。</p><p>我那些漂亮的照片本身毫无意义。我不能只是发帖，然后祈祷我们的救世主——“算法”来拯救我。</p><p><em>我必须让我的内容呈现在人们面前。</em></p><p><em>我必须让拥有比我更多受众的人分享我的内容。</em></p><p>（从宏观来看，这就是社交媒体增长的唯一原则，即使你在主持X Spaces，或者受邀在别人的播客里分享你的口头内容也是如此。）</p><p>在数字艺术领域，有很多精选合集账号（curation accounts）。</p><p>这些账号每天都会发布他们最喜欢的数字艺术作品，并圈出（tag）创作者（creator）。</p><p>你只有圈出他们，使用他们的标签，与他们互动，并可能还要私信他们建立关系，才有机会被这些账号看到。</p><p>我坚持了两个月。</p><p>我知道我必须创作出其他账号<em>想要</em>分享的优质内容。</p><p>如果我没记错的话，我的帖子被各种规模的账号分享了30-40次。</p><p>像“A Game Of Tones”这样的账号就是头奖。如果你能被他们分享，你的粉丝数就会一飞冲天。被10万到50万粉丝的账号分享所带来的多巴胺飙升简直令人疯狂。</p><p>在最初的2个月里，我的Instagram从0粉涨到了2500粉。</p><p>从我自己和我的学生们的经验来看，前1万粉总是最难的。</p><p>到了这个时候，我精疲力竭，放弃了。</p><p>我不想让自己维持着对兴奋剂的依赖，每天花8个小时就为了做出一张Photoshop合成图。</p><p>而且，我不懂营销，也不懂销售。</p><p>如果我围绕我如何创作艺术制作一款教育产品，我本可以大赚一笔（艺术家们，记好笔记了，几乎所有大艺术家都有课程或教程库是有原因的。卖那些好卖的东西）。</p><p>这次运营社交媒体品牌短暂的失败，教会了我什么是增长真正必需的条件：</p><p>让优质内容出现在他人面前——这是你让别人关注你的唯一机会。</p><p>但是要做到这一点，有很多正确的方法。</p><p>我们来谈谈你可以利用（leverage）的每一种增长机制，按优先级排序。</p><h2 id="宏观视角——如何在社交媒体上实现增长" tabindex="-1">宏观视角——如何在社交媒体上实现增长 <a class="header-anchor" href="#宏观视角——如何在社交媒体上实现增长" aria-label="Permalink to &quot;宏观视角——如何在社交媒体上实现增长&quot;">​</a></h2><p>我不再做Photoshop艺术创作了。</p><p>我现在是一名作家，这是<a href="https://thedankoe.com/blog/category/digital-writing/" target="_blank" rel="noreferrer">数字作家系列（Digital Writer series）</a>的一部分，所以我们将从这个视角来探讨——如何让你的文字被分享。（如果你想了解写什么以及如何写的入门知识，<a href="/letters/dont-get-replaced-by-ai-how-to-write-authentic-content">阅读这封关于撰写真实内容的信</a>）。</p><p>我说的文字，是指在社交媒体上写下的任何东西，这几乎囊括了一切。</p><p>文案、带文字图片的Instagram帖子、推文、LinkedIn帖子、短视频脚本、YouTube脚本等等。</p><p>社交媒体的增长是如此简单直接，以至于所有人都把它想得太复杂了，或者他们根本就不关注它。</p><p>有些人发帖、发帖、不断发帖，结果却因为算法没有传播他们的内容而大发雷霆。</p><p>另一些人知道如何增长，他们也是聪明人，但他们的帖子就像永远卖不出去的艺术品。艺术家认为它们是世界上最好的东西，但市场根本不在乎。</p><p>还有一些人，他们获得了一点增长，却不知道如何在自己最好的想法上加倍投入，以实现增长的复利。</p><p><strong>1) 撰写具有说服力的内容</strong></p><p>这里的关键词是“说服力”。</p><p>说服力意味着几件事：</p><ul><li><strong>一个钩子（A hook）</strong>。留心你的第一句话是否能抓住他们的注意力。这不仅仅取决于你使用的词语。帖子的结构和排版也能做到这一点，即使在X上也是如此。</li><li><strong>一个大问题</strong>。暗示或陈述一个人们能产生共鸣的问题。不要把它说得太高深。</li><li><strong>一个清晰的解决方案</strong>。一个可以克服该问题的可行方法，最好是源于个人经验的独特方法。</li><li><strong>一个巨大的好处</strong>。暗示或陈述人们从你的建议中能获得的一种令人向往的收益。</li><li><strong>自信或极化（Polarization）</strong>。坚定你的信念，但也愿意改变它们。没人想去关注一个听起来不自信或者连边都站不好的人。想说什么就说什么。你会像其他人一样招来非议。</li><li><strong>一个新颖的视角或大思想</strong>。这就是为什么阅读或消费内容很重要。如果你能找到一种不同寻常的方式来解释某个观点，它会给你的读者带来多巴胺的冲击，并深化他们的理解。</li></ul><p>将这些内容巩固在脑海中的最佳方法是把它们保存在安全的地方，并尝试在你看到的在线内容中找出它们。</p><p>我将在下一封信中详细介绍10个策略，让你的写作更具吸引力（附带案例）。</p><p>我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">《两小时作者》（2 Hour Writer）</a>中教授了所有这些内容（如何写作并围绕你的兴趣建立品牌）。</p><p><strong>2) 让你的内容被看到</strong></p><p>我们已经讨论过这一点，并将在下一节深入探讨。</p><p>现在，请牢牢记住：如果你的内容没人看，那它就毫无意义。这应该是常识。</p><p>为了练习而对着空气写内容没问题，但不要因为害怕增长和面对批评，就把这当成借口。</p><p><strong>3) 利用数据迭代你的想法</strong></p><p>只有当你的内容有人看时，你才能走到这一步。</p><p>如果你的内容没有任何互动，你就不知道哪些想法对你最有效。</p><p>当你有互动时，每个月在数据分析中回顾你表现最好的内容。把它们复制粘贴到一个笔记文档中。</p><p>当你打算写更多内容时，融入这些想法，并从不同的角度去写它们。</p><p>这就是你随着时间推移提高参与度的方法。</p><p><strong>4) 为你最好的想法拓展深度与广度</strong></p><p>你可以在X这样的单一平台上做得很好，但你最终会成为那个平台的奴隶。</p><p>你必须不断使用增长策略，才能让你的内容保持在人们眼前。它的生命周期不会很长。</p><p>现代的权力属于那些在一生中掌握最多注意力的人。</p><p>一篇只能吸引10秒注意力的短帖，与一个能锁定15-60分钟注意力的视频、播客或时事通讯相比，根本不值一提。</p><p>你必须把最好的想法（来自上一节）转化为更长篇幅的内容。</p><p>这就是你毫不费力就能让名声远播的方法。</p><p>这就是你把品牌的根基深植于大众集体心理的方法。</p><p>这就是你建立比那些只发短内容的人高出几个数量级的信任和权威的方法。</p><p>这就是为什么你几乎总是把你人生中的成就归功于一本书或一位教会你方法的作者。</p><p>即使有人在社交媒体上谈论同样的观点，当你读到它时，那位作者也会浮现在你的脑海中（并占据你的注意力）。</p><h2 id="流量机制——如何让你的文字被分享" tabindex="-1">流量机制——如何让你的文字被分享 <a class="header-anchor" href="#流量机制——如何让你的文字被分享" aria-label="Permalink to &quot;流量机制——如何让你的文字被分享&quot;">​</a></h2><p>既然你已经满怀希望能开始写作并发布内容了，那么了解社交媒体这场游戏的机制会大有裨益。</p><p>当你明白这些机制如何让你实现增长时，你就可以创造性地让你的内容被分享出去。</p><p>以下排名不分先后。</p><p>全都试一遍，看看哪个效果最好。</p><p>别掉进那些社交媒体“大师”的陷阱里，听他们跟你吹嘘说某种方法比另一种更好，仅仅是因为算！法！变！了！！！</p><p><strong>1) 回复</strong></p><p>这是每个人都在做、最显而易见的一个。</p><p>如果你回复了别人的帖子，当读者点进评论区时，他们就有机会看到你的回复。</p><p>如果你的回复很赞，他们可能会点击你的主页，阅读你的内容，如果发现你的内容也不错，就会关注你。</p><p>在这里人们容易忽略几件事：</p><ul><li><strong>无聊的内容不会让人去读回复</strong>。我整天看到人们去回复无聊的帖子，回复也没什么曝光量。然后他们纳闷到底是因为什么出了错。</li><li><strong>无聊的回复不会让人点击你的主页</strong>。别再重复原帖里已经说过的话了。在这里谈谈你自己。告诉大家你在生活中是如何经历同样的事情的。谈论你自己能带来最多的主页点击量。</li><li><strong>小账号整体上获得的曝光量较少</strong>。去回复与你规模相当的账号并与他们建立联系是件好事，但别指望这能帮你增长多少（没关系，你还是应该这样做）。只要确保你也在回复那些拥有有趣内容的大账号即可。</li></ul><p><strong>2) 引用发帖（Quote Posts）</strong></p><p>引用发帖是指有人转发你的内容并附上他们自己的评论。这可以发生于在X上，或者当有人将你的帖子分享到他们的IG Story（快拍）并附上他们自己的评论时。</p><p>在X上，如果你知道如何撰写有说服力的内容，这招会非常有效。</p><p>如果你引用了某人的帖子，并附上了有价值的建议或有趣的想法，原创创作者可能会将你转发给他们的受众。这意味着你的内容获得了更多关注，从而增加了人们点击你主页并关注你的潜力。</p><p>在这里要当心，不要像对待“回复”那样把目标定得太高。</p><p>头部创作者（Bigger creators）的消息通知实在太多了，他们很可能会错过你的帖子。</p><p>要能够从你试图利用（leverage）的那位创作者受众的视角，来审视你的增长努力。</p><p><strong>3) 转发（Reposts）</strong></p><p>你的内容必须足够优秀，且足够能让人产生共鸣，人们才会想要分享到他们的信息流中。</p><p>在点击发布之前，一定要把这一点想清楚。</p><p>人们会分享它吗？他们为什么要分享它？他们认同我说的内容吗？它是否足够两极分化，从而引发讨论并获得评论？</p><p><strong>4) 手动发私信</strong></p><p>这个方法更困难也更慢，但它对于建立人脉和让大账号分享你的帖子很有效（前提是你是个正常人，而不是那种在私信里像个领英职场机器人的家伙）。</p><p>没有人<em>想</em>收到这样的信息：“嘿！很高兴认识你！我超爱你的东西！我们应该喝杯虚拟咖啡，聊聊Zapier自动化的复杂性，以此提升你忠实邮件订阅用户的整体体验，这样你就能建立一个不可思议的数字形象了！！！！”</p><p>你可以在网上交朋友，交到那种只要是你发的东西，他们都很乐意分享的地步。</p><p>这是一篇关于我的<a href="/letters/how-to-network-with-millionaires-and-build-a-name-for-yourself">无需求感社交过程（Non-Needy Networking Process）</a>的信。明智地运用它，千万别照抄我说的话。</p><p>手动发私信的方法也可以转化为一种控制你增长的方法。</p><p>发1条私信可能只会给你的帖子带来1次曝光，但如果你能进行一次真诚的交流，他们分享这些帖子的潜力就会更高。</p><h2 id="如何在任何平台上控制你的增长" tabindex="-1">如何在任何平台上<em>控制</em>你的增长 <a class="header-anchor" href="#如何在任何平台上控制你的增长" aria-label="Permalink to &quot;如何在任何平台上*控制*你的增长&quot;">​</a></h2><p>如果你很聪明，你可以创造性地运用我们讨论过的任何流量机制来控制你的增长。</p><p>如果你不想成为算法的奴隶，这些是你唯一能用来增长的工具。</p><p><strong>1) 从短内容到长内容</strong></p><p>像X、Instagram和TikTok这样的短内容平台，天生就比YouTube或播客更容易实现增长。</p><p>你可以写更多通过我们讨论过的流量机制被分享的内容。</p><p>拼了老命我也没能在YouTube上实现增长，但我知道如何在X上控制我的增长。</p><p>所以我在这两个平台上都发布内容，并随着时间推移将我的受众引流到YouTube。</p><p>你没必要非得照着我这里说的做，但考虑到每个人都想成为YouTuber，这条路是说得通的。</p><p>你可能必须走一条更聪明的路，而这就是其中之一。</p><p><strong>2) 策展、引用与混搭</strong></p><p>DJ和制作人通过混音流行歌曲来实现增长，这样他们就能“窃取”那首流行歌曲的流量。</p><p>有时他们会在Instagram上发布带有他们混音作品的短片（reels），而原唱歌手（通常拥有大量粉丝和影响力）会将其分享到他们的主页或快拍（story）上。</p><p>这和我以前做数字艺术时的情况类似。</p><p>我可以混搭别人的艺术作品，打上他们的标签，就有可能被分享。</p><p>对于写作者来说同样如此。</p><p>你可以：</p><ul><li><strong>在推文串或时事通讯中引用他们</strong>。在你的长文中使用他们的想法来阐明一个观点。然后私信给他们这篇帖子，说你提到了他们。他们可能不用你开口就会转发。</li><li><strong>评论他们的内容</strong>。类似于YouTuber制作反应视频，以此来利用头部创作者获得的流量作为杠杆。</li><li><strong>邀请别人上播客</strong>。人们喜欢上播客。这是你向更大创作者受众曝光的方式。他们会分享播客让自己的受众去观看或收听。</li><li><strong>谈论他们的想法并给予署名</strong>。发一篇简单的帖子，比如“我这周看到的最佳想法：”，接着解释它对你产生了怎样的影响，并标注原作者。</li></ul><p>这强调了长内容与短内容相结合的重要性。在短内容帖子中很难做到这一点。</p><p>当然，你可以在像X这样的平台上写长篇帖子，以此利用这一策略作为杠杆。</p><p><strong>3) 付费增长</strong></p><p>这个话题有点敏感。</p><p>那些“超级真实”、道德高尚的人（他们同时对社交媒体零经验）喜欢吹嘘自己不使用付费增长策略是有多么真实和高尚。</p><p>我多年来一直在观察这些人，4年过去了，他们要么完全没有增长，要么掉粉了。</p><p>人们不喜欢满腹牢骚的抱怨者，这些人不再专注于提供价值，也不再推动更全面的世界观。</p><p>听着，我说的不是投广告涨粉。那是你能做的最糟糕的事情。千万别这么干。我再说一遍，千万别这么干。</p><p>我也不是在说花钱在Instagram上买推广（shoutouts），就是你付钱给一个大型主题账号来发布你的内容，并大声吆喝让人们来关注你。</p><p>那种都是空有50万粉丝但互动率为零的账号。</p><p>我说的是发布一篇真正真实的内容，然后用一点钱来放大你的效果。</p><p>好内容是先决条件。</p><p>我所说的付费增长，是付钱给那些与你产生共鸣的大号，让他们花时间在上述的某一种流量机制上。</p><p>大号都很忙，除非你付钱买他们的注意力，否则他们很可能不会这么做。这并不不公平。这就是现实。你不了解他们正在建立的那些占据了他们注意力的东西。</p><p><strong>你可以让他们转发你。</strong></p><p>在X上，这就相当于让他们分享你的帖子。</p><p>在Instagram上，这就是让他们把你的帖子分享到他们的快拍。</p><p>不要让他们说任何话或标记你。</p><p>让读者看到你的内容，如果他们愿意自然会关注你。</p><p><strong>你可以让他们回复你。</strong></p><p>当像X这样的平台开始倾向于评论时，这招非常管用。</p><p>这对你付费的创作者来说通常更容易，因为他们不需要在自己的信息流里分享东西。</p><p>你真的可以让他们做任何事。</p><p>私信他们，问问他们是否提供增长帮助，把对话转移到其他地方，然后谈个交易。</p><p>在我看来，要想为你的产品或服务变现，这是一种比付费广告或其他任何方式都要好得多的方法。</p><p>用真实的分享来建立你的受众，让人们因为喜欢你的内容而关注你，然后随着受众的增长向他们推广你的报价（offer）。</p><p>如果你认为广告商把产品随机糊到你脸上是可以接受的，那我就不明白为什么你会认为创作者收钱分享内容（你可能还会喜欢的内容）并且不要求你买任何东西就不行。</p><p><strong>4) 智囊团（Masterminds）</strong></p><p>残酷的真相：</p><p>你所认识的每一个创作者都在一个与其他创作者合建的群聊里。</p><p>他们一起讨论策略，并享受共同打造业务的乐趣。</p><p>他们也会分享彼此的帖子，帮助互相增长。</p><p>他们利用流量机制来创造一种可以融入日常工作的策略。</p><p>有些群组每天早上会在彼此的帖子下评论。</p><p>另一些则会转发在群里分享的帖子。</p><p>最重要的是，他们形成了一个部落，并开始认同自己是这个群体的一部分。</p><p>你可能会注意到网上有5到10个创作者组成的小部落，他们经常在网上互相交流。这就是原因。</p><p>是的，你必须去私信别人，交朋友，让这些关系近乎自然地建立起来。</p><p>这是一场长期游戏。</p><p>坚持做所有这些事，你也无法在不到一年的时间里看到惊人的结果。</p><p>即使那样，你仍然可以在增长的过程中使用其他策略来进行变现。</p><p>这次的内容就到这里。</p><p>感谢你的阅读。</p><p>Dan Koe</p><p>附注：我在 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> 中教授数字写作。它不仅仅是“学习写作”。它为你提供了一个每天可以执行的系统，以便你能以此为生。</p><hr><p><a href="/en/letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',177))])}const T=r(h,[["render",u]]);export{b as __pageData,T as default};
